"""Writes data/scam_rules.json (shared by Python backend AND the website) and data/sample_scams.csv (480 rows).
SYNTHETIC template-generated demo data, NOT real messages."""
import csv, json, random
from pathlib import Path
R = random.Random(11); D = Path(__file__).parent/"data"; D.mkdir(exist_ok=True)
r_ = lambda cat,w,crit,re,title,expl,type="": dict(cat=cat,w=w,crit=crit,re=re,title=title,expl=expl,type=type)
RISK = [
 r_("Phishing",30,1,r"kyc\s*(update|expired|expire|pending|verification|suspended)|account\s+(will\s+be|has\s+been|is)\s+(blocked|suspended|closed|frozen|deactivated)|verify\s+your\s+(account|identity|details)|update\s+your\s+(pan|aadhaar|aadhar|bank|card|details)|click\s+(here|the\s+link|below)\s+to\s+(verify|update|unlock|claim)|unusual\s+activity","Account-verification / KYC pressure","Banks do not ask you to verify details through links in messages.","Phishing / bank KYC fraud"),
 r_("Credentials",35,1,r"(share|send|tell|give|provide|enter|read\s+out)\s+(me\s+|us\s+|the\s+)?(your\s+|the\s+)?(otp|pin|cvv|password|code\s+you\s+(just\s+)?received)","Asks for OTP / PIN / password","No bank or company will ever ask for your OTP, PIN or CVV.","Credential / OTP theft"),
 r_("Prize",28,1,r"you\s+(have\s+)?won|selected\s+for\s+a\s+prize|\bwinner\b|prize\s+of|lottery|lucky\s+draw|lucky\s+winner|prize\s+(money|amount)|claim\s+your\s+(prize|reward|gift)|congratulations.{0,40}(winner|won|selected\s+for)","Prize / lottery claim","You cannot win a contest you never entered.","Lottery / prize scam"),
 r_("Payment",30,1,r"(processing|clearance|customs|release|gst|tax|redelivery|registration)\s+(fee|fees|charges?)|pay\s+(a\s+)?(small\s+)?(fee|fine|deposit|charges?)\s+(to|of|for)","Upfront fee demanded","Legitimate prizes, loans and parcels do not need advance fees.","Advance-fee scam"),
 r_("Investment",26,1,r"guaranteed\s+(returns?|profit)|double\s+your\s+(money|investment)|\d{2,3}%\s*(returns?|profit)\s*(daily|weekly|monthly)|risk[-\s]free|insider\s+(tip|trading)|crypto\s+(signal|trading|investment)|forex|join\s+(our\s+)?(vip|premium)\s+(group|channel)","Guaranteed-returns investment pitch","Guaranteed high returns are a hallmark of investment fraud.","Investment / crypto scam"),
 r_("Loan app",22,1,r"(access|permission)\s+to\s+(your\s+)?(contacts|gallery|photos)|no\s+(cibil|documents?|credit\s+check)|instant\s+loan|loan\s+(is\s+)?approved|pre-?approved\s+(personal\s+)?loan","Instant-loan bait","Predatory loan apps steal contacts and harass borrowers.","Predatory loan app"),
 r_("Delivery",22,0,r"(parcel|package|courier|shipment).{0,40}(held|stuck|returned|undelivered|customs|could\s+not\s+be\s+delivered)|redelivery|address\s+(is\s+)?(incomplete|invalid)|track\s+your\s+(parcel|package)\s+at","Fake parcel / delivery notice","Check delivery status only in the courier's official app.","Fake delivery scam"),
 r_("Impersonation",32,1,r"\b(cbi|ed|police|customs|narcotics|cyber\s*crime|trai|income\s*tax|rbi|court)\b.{0,70}(arrest|warrant|case|fir|legal\s+action|blocked)|digital\s+arrest|money\s+laundering|your\s+(sim|number|aadhaar)\s+(will\s+be|is)\s+(blocked|suspended|misused)","Authority impersonation / 'digital arrest'","No agency arrests or interrogates people over a call or video chat.","Authority impersonation / digital arrest"),
 r_("UPI",30,1,r"(refund|cashback|reward).{0,50}(scan|qr|upi\s+pin|collect\s+request)|enter\s+(your\s+)?upi\s+pin|accept\s+the\s+(collect|payment)\s+request|scan\s+(this\s+)?qr(\s+code)?\s+to\s+(receive|get)","UPI / QR 'refund' trick","You never need a PIN or QR scan to RECEIVE money.","UPI / QR refund scam"),
 r_("Tech support",28,0,r"(virus|malware|hacked).{0,50}(call|contact)|call\s+(our\s+)?(toll[-\s]free|support|technician)|install\s+(anydesk|teamviewer|quicksupport)|remote\s+(access|support)","Fake tech-support / remote access","Never install remote-control apps for a stranger.","Tech-support scam"),
 r_("Emotional",16,0,r"(i\s+am|i'm)\s+(stuck|stranded|in\s+trouble)|send\s+(me\s+)?(money|gift\s*cards?)|urgent(ly)?\s+need\s+(money|cash|help)|(army|military|oil\s+rig|overseas)\s+(officer|engineer)","Emergency / romance money request","Scammers invent emergencies to get quick money.","Romance / emergency scam"),
 r_("Pressure",10,0,r"within\s+\d+\s+hours?|act\s+(now|immediately)|last\s+(chance|warning)|expires?\s+(today|soon)|final\s+notice|\burgent\b|immediately","Urgency / time pressure","Scammers rush you so you cannot think or verify."),
 r_("Pressure",16,0,r"do\s+not\s+tell\s+(anyone|your\s+family)|don't\s+tell\s+(anyone|your\s+family)|keep\s+this\s+(confidential|secret)","Secrecy / isolation demand","Fraudsters isolate victims so no one can warn them."),
 r_("Payment",20,0,r"gift\s*cards?|bitcoin|usdt|wire\s+transfer|western\s+union","Untraceable payment method","Scammers prefer payments that cannot be reversed."),
 r_("Link",12,0,r"\b(bit\.ly|tinyurl\.com|goo\.gl|cutt\.ly|rb\.gy)\S*","Shortened link","Hides the real destination."),
 r_("Pressure",8,0,r"will\s+be\s+(blocked|terminated|arrested)|legal\s+action|penalty","Threat language","Threats are used to cause panic.")]
GOOD = [dict(w=10,re=r"never\s+share|do\s+not\s+share|if\s+this\s+wasn't\s+you|visit\s+(your\s+)?branch|official\s+(app|website)",title="Contains official safety advice"),
        dict(w=6,re=r"debited|credited|a/c\s*(no\.?)?\s*x+\d+|ref(erence)?\s*(no|number)",title="Looks like a transaction notification"),
        dict(w=6,re=r"no\s+action\s+(is\s+)?required|for\s+your\s+information|thanks\s+for\s+shopping|reminder:",title="Informational message, no action demanded")]
BRANDS = r"sbi|hdfc|icici|axis|kotak|paytm|phonepe|gpay|google|amazon|flipkart|microsoft|apple|netflix|irctc|india\s*post|fedex|dhl|bluedart"
json.dump(dict(risk=RISK,good=GOOD,brands=BRANDS),open(D/"scam_rules.json","w"),indent=1)
BANK=["SBI","HDFC Bank","ICICI Bank","Axis Bank","Kotak"]; CO=["Amazon","Flipkart","Myntra","Swiggy"]
LNK=["http://sbi-kyc-update.xyz/login","https://bit.ly/3xKyc","http://hdfc-secure-verify.top","www.amaz0n-prize.click/claim","http://192.168.4.21/pay","https://paytm-refund.work","http://india-post-redeliver.icu"]
AMT=["5,000","25,000","50,000","1,00,000","9,999","2,50,000"]
S={"phishing":["Dear customer, your {b} KYC has expired. Your account will be blocked within 24 hours. Click {l} to update your PAN now.","{b} ALERT: Unusual activity detected. Verify your account immediately at {l} or it will be suspended.","Your {b} reward points worth Rs {a} expire today. Update your details at {l} to redeem."],
"otp":["This is {b} support. To stop the unauthorized transaction please share your OTP with our executive now.","Send me the code you just received so I can verify your account, also share your CVV.","Your account is under review. Provide your PIN and password to the agent to avoid closure."],
"lottery":["Congratulations! You have won Rs {a} in the {c} lucky draw. Claim your prize now at {l}.","You are the lucky winner of a lottery of Rs {a}. Pay a Rs 2,500 processing fee to release the prize money.","Dear winner, your number was selected for a prize of {a} dollars. Contact the claims officer on WhatsApp."],
"investment":["Join our VIP crypto signals group. Guaranteed 30% returns weekly, risk free. Limited seats, message on Telegram.","Double your money in 7 days with our forex trading plan. Insider tips daily, 100% profit guaranteed.","Earn passive income: invest Rs {a} and get 5% daily returns. Join our premium channel now."],
"loan_app":["Instant loan approved up to Rs {a}. No documents, no CIBIL check. Install our app and allow access to contacts and gallery.","Pre-approved personal loan of Rs {a}, no collateral. Click {l} to get funds in 5 minutes.","Your loan is approved! Pay a processing fee of Rs 999 to receive the amount in your account."],
"delivery":["Your parcel is held at the depot because the address is incomplete. Pay a redelivery fee of Rs 25 at {l}.","Courier alert: package stuck in customs. Track your parcel at {l} and pay the clearance charges.","Your shipment could not be delivered. Update your address within 12 hours at {l} or it will be returned."],
"authority":["This is the CBI cyber crime branch. A case has been registered against your Aadhaar for money laundering. You are under digital arrest, do not tell anyone.","TRAI notice: your SIM number will be blocked within 2 hours due to illegal activity. Call this officer immediately.","Customs department: a parcel in your name contains narcotics. A warrant will be issued. Pay a fine to settle the case."],
"upi_refund":["Dear customer, your refund of Rs {a} is pending. Scan this QR code to receive the money and enter your UPI PIN.","Cashback of Rs {a} credited. Accept the collect request on your UPI app to receive it.","To get your refund, scan this QR to receive and enter your UPI PIN to confirm."],
"tech_support":["Your computer is hacked and has a virus. Call our toll free technician now. Install AnyDesk so we can fix it remotely.","Microsoft alert: malware detected. Call support immediately to avoid data loss, remote access required."],
"romance":["I am an army officer stranded overseas. I urgently need money, please send gift cards, do not tell anyone.","Hi dear, I'm in trouble and need urgent help. Send me money today, keep this secret."]}
SAFE=["{b}: Rs {a} debited from A/c XX{n} on 12-Oct. Ref no {n}77. If this wasn't you, visit your branch or call the number on your card. Never share your OTP.","{n}9 is your OTP for the transaction of Rs {a}. Do not share this OTP with anyone. It is valid for 10 minutes.","Your {c} order #{n} is out for delivery today. Track it in the official app.","Reminder: your appointment with Dr. Rao is tomorrow at 5 PM. Reply YES to confirm.","Hey, are we still meeting at 6 PM? I will bring the notes for the exam.","Thanks for shopping at {c}. Your invoice #{n} for Rs {a} is attached. No action required.","Your electricity bill of Rs {a} is due on 25-Oct. Pay through the official app or website to avoid a late fee.","{b}: KYC update is due. Please visit your branch with documents. We never ask for details by link.","Hi, the class is moved to Room 204 tomorrow. Please inform others.","Your {c} refund of Rs {a} has been processed to the original payment method. No action required."]
rows=[]
for i in range(240):
    t=R.choice(list(S)); f=R.choice(S[t]).format(b=R.choice(BANK),a=R.choice(AMT),c=R.choice(CO),l=R.choice(LNK)); rows.append(dict(text=f,label=1,scam_type=t))
    f=R.choice(SAFE).format(b=R.choice(BANK),a=R.choice(AMT),c=R.choice(CO),n=R.randint(1000,9999)); rows.append(dict(text=f,label=0,scam_type="safe"))
R.shuffle(rows)
with open(D/"sample_scams.csv","w",newline="",encoding="utf-8") as fh:
    w=csv.DictWriter(fh,fieldnames=["text","label","scam_type"]); w.writeheader(); w.writerows(rows)
print("wrote",len(rows))
